import { redirect } from 'next/navigation'

/**
 * Legacy OTP screen. Email and phone codes are now generated by AseHanta and
 * delivered through Brevo, so this Supabase-OTP screen is no longer used.
 */
export default async function LegacyVerifyPage({
  searchParams,
}: {
  searchParams: Promise<{ callbackUrl?: string }>
}) {
  const { callbackUrl } = await searchParams
  const target = callbackUrl && callbackUrl.startsWith('/') ? callbackUrl : ''
  redirect(target ? `/auth/signin?callbackUrl=${encodeURIComponent(target)}` : '/auth/signin')
}
